-- ===========================================================
-- TELECOM DATABASE  —  schema + data combined
-- Run this ONE file to get everything
-- MySQL 8.0+
-- ===========================================================

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = '';

DROP DATABASE IF EXISTS telecom;
CREATE DATABASE telecom
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE telecom;

-- ===========================================================
-- SCHEMA
-- ===========================================================

CREATE TABLE countries (
  country_code  CHAR(2)       NOT NULL,
  country_name  VARCHAR(100)  NOT NULL,
  currency_code CHAR(3)       NOT NULL,
  CONSTRAINT pk_countries PRIMARY KEY (country_code)
);

CREATE TABLE regions (
  region_id    INT          NOT NULL AUTO_INCREMENT,
  country_code CHAR(2)      NOT NULL,
  region_name  VARCHAR(100) NOT NULL,
  region_type  VARCHAR(20)  NOT NULL,
  CONSTRAINT pk_regions PRIMARY KEY (region_id),
  CONSTRAINT fk_reg_country
    FOREIGN KEY (country_code) REFERENCES countries (country_code)
);

CREATE TABLE plan_families (
  family_id   INT          NOT NULL AUTO_INCREMENT,
  family_name VARCHAR(100) NOT NULL UNIQUE,
  CONSTRAINT pk_plan_families PRIMARY KEY (family_id)
);

CREATE TABLE plans (
  plan_id         INT           NOT NULL AUTO_INCREMENT,
  family_id       INT           NOT NULL,
  plan_name       VARCHAR(100)  NOT NULL UNIQUE,
  plan_type       VARCHAR(20)   NOT NULL,
  monthly_fee     DECIMAL(10,2) NOT NULL,
  data_limit_gb   DECIMAL(8,2)  DEFAULT NULL,
  contract_months INT           NOT NULL DEFAULT 0,
  is_active       TINYINT(1)    NOT NULL DEFAULT 1,
  CONSTRAINT pk_plans PRIMARY KEY (plan_id),
  CONSTRAINT fk_plans_family
    FOREIGN KEY (family_id) REFERENCES plan_families (family_id)
);

CREATE TABLE subscribers (
  subscriber_id INT          NOT NULL AUTO_INCREMENT,
  country_code  CHAR(2)      NOT NULL,
  full_name     VARCHAR(200) NOT NULL,
  email         VARCHAR(255) NOT NULL UNIQUE,
  status        VARCHAR(20)  NOT NULL DEFAULT 'Active',
  signup_date   DATE         NOT NULL,
  churn_date    DATE         DEFAULT NULL,
  CONSTRAINT pk_subscribers PRIMARY KEY (subscriber_id),
  CONSTRAINT fk_sub_country
    FOREIGN KEY (country_code) REFERENCES countries (country_code)
);

CREATE TABLE sims (
  sim_id        INT         NOT NULL AUTO_INCREMENT,
  subscriber_id INT         NOT NULL,
  msisdn        VARCHAR(20) NOT NULL UNIQUE,
  status        VARCHAR(20) NOT NULL DEFAULT 'Active',
  activated_at  DATE        NOT NULL,
  CONSTRAINT pk_sims PRIMARY KEY (sim_id),
  CONSTRAINT fk_sim_sub
    FOREIGN KEY (subscriber_id) REFERENCES subscribers (subscriber_id)
);

CREATE TABLE sim_plan_history (
  history_id INT  NOT NULL AUTO_INCREMENT,
  sim_id     INT  NOT NULL,
  plan_id    INT  NOT NULL,
  start_date DATE NOT NULL,
  end_date   DATE DEFAULT NULL,
  CONSTRAINT pk_sim_plan_history PRIMARY KEY (history_id),
  CONSTRAINT fk_sph_sim
    FOREIGN KEY (sim_id)  REFERENCES sims  (sim_id),
  CONSTRAINT fk_sph_plan
    FOREIGN KEY (plan_id) REFERENCES plans (plan_id)
);

CREATE TABLE billing_cycles (
  cycle_id      INT  NOT NULL AUTO_INCREMENT,
  subscriber_id INT  NOT NULL,
  cycle_start   DATE NOT NULL,
  cycle_end     DATE NOT NULL,
  CONSTRAINT pk_billing_cycles PRIMARY KEY (cycle_id),
  CONSTRAINT fk_cyc_sub
    FOREIGN KEY (subscriber_id) REFERENCES subscribers (subscriber_id),
  CONSTRAINT uq_sub_cycle UNIQUE (subscriber_id, cycle_start)
);

CREATE TABLE bills (
  bill_id       INT           NOT NULL AUTO_INCREMENT,
  cycle_id      INT           NOT NULL UNIQUE,
  subscriber_id INT           NOT NULL,
  bill_date     DATE          NOT NULL,
  due_date      DATE          NOT NULL,
  total_amount  DECIMAL(10,2) NOT NULL,
  amount_paid   DECIMAL(10,2) NOT NULL DEFAULT 0,
  status        VARCHAR(20)   NOT NULL DEFAULT 'Unpaid',
  CONSTRAINT pk_bills PRIMARY KEY (bill_id),
  CONSTRAINT fk_bill_cycle
    FOREIGN KEY (cycle_id)      REFERENCES billing_cycles (cycle_id),
  CONSTRAINT fk_bill_sub
    FOREIGN KEY (subscriber_id) REFERENCES subscribers    (subscriber_id)
);

CREATE TABLE usage_logs (
  log_id       BIGINT        NOT NULL AUTO_INCREMENT,
  sim_id       INT           NOT NULL,
  log_date     DATE          NOT NULL,
  data_used_gb DECIMAL(10,4) NOT NULL DEFAULT 0,
  call_minutes INT           NOT NULL DEFAULT 0,
  sms_count    INT           NOT NULL DEFAULT 0,
  CONSTRAINT pk_usage_logs PRIMARY KEY (log_id),
  CONSTRAINT fk_usage_sim
    FOREIGN KEY (sim_id) REFERENCES sims (sim_id)
);

CREATE TABLE support_tickets (
  ticket_id     INT         NOT NULL AUTO_INCREMENT,
  subscriber_id INT         NOT NULL,
  category      VARCHAR(50) NOT NULL,
  priority      VARCHAR(10) NOT NULL DEFAULT 'Medium',
  status        VARCHAR(20) NOT NULL DEFAULT 'Open',
  opened_at     DATETIME    NOT NULL,
  resolved_at   DATETIME    DEFAULT NULL,
  CONSTRAINT pk_support_tickets PRIMARY KEY (ticket_id),
  CONSTRAINT fk_ticket_sub
    FOREIGN KEY (subscriber_id) REFERENCES subscribers (subscriber_id)
);

